bool USaveGameComponent::SaveGame(FName SlotName)
{
	UWorld* World = GetWorld();
	if (!World) return false;
	UDeepSpaceTraderSaveGame* SaveObject = Cast<UDeepSpaceTraderSaveGame>(UGameplayStatics::CreateSaveGameObject(UDeepSpaceTraderSaveGame::StaticClass()));
	if (!SaveObject) return false;

	AActor* Owner = GetOwner();
	if (Owner)
	{
		if (UInventoryTradeComponent* Inventory = Owner->FindComponentByClass<UInventoryTradeComponent>())
		{
			SaveObject->PlayerCredits = Inventory->GetCredits();
			SaveObject->PlayerCargo = Inventory->GetCargo();
		}
		if (UMissionComponent* Missions = Owner->FindComponentByClass<UMissionComponent>())
		{
			SaveObject->ActiveMissions = Missions->ActiveMissions;
			SaveObject->AvailableMissions = Missions->AvailableMissions;
			SaveObject->CompletedMissions = Missions->CompletedMissions;
			SaveObject->FailedMissions = Missions->FailedMissions;
		}
		if (UFactionComponent* Factions = Owner->FindComponentByClass<UFactionComponent>())
		{
			SaveObject->FactionStandings = Factions->FactionStandings;
			SaveObject->FactionRelationships = Factions->FactionRelationships;
		}
		if (UShieldComponent* Shield = Owner->FindComponentByClass<UShieldComponent>())
		{
			SaveObject->CurrentShield = Shield->GetCurrentShield();
		}
		if (UDamageComponent* Damage = Owner->FindComponentByClass<UDamageComponent>())
		{
			SaveObject->CurrentHullHealth = Damage->CurrentHullHealth;
		}
		// CurrentFuel/CurrentShipClass/SubsystemHealth/CurrentStation have no live
		// source-of-truth components yet — intentionally left unwired (no fake data).
		SaveObject->PlayerLocation = Owner->GetActorLocation();
		SaveObject->PlayerRotation = Owner->GetActorRotation();
	}

	SaveObject->SaveTimestamp = FDateTime::Now();
	const bool bSaved = UGameplayStatics::SaveGameToSlot(SaveObject, *SlotName.ToString(), 0);
	UE_LOG(LogTemp, Log, TEXT("SaveGame '%s': %s"), *SlotName.ToString(), bSaved ? TEXT("ok") : TEXT("FAILED"));
	return bSaved;
}

bool USaveGameComponent::LoadGame(FName SlotName)
{
	UWorld* World = GetWorld();
	if (!World) return false;
	UDeepSpaceTraderSaveGame* SaveObject = Cast<UDeepSpaceTraderSaveGame>(UGameplayStatics::LoadGameFromSlot(*SlotName.ToString(), 0));
	if (!SaveObject)
	{
		UE_LOG(LogTemp, Warning, TEXT("LoadGame '%s': no such slot"), *SlotName.ToString());
		return false;
	}

	AActor* Owner = GetOwner();
	if (Owner)
	{
		if (UInventoryTradeComponent* Inventory = Owner->FindComponentByClass<UInventoryTradeComponent>())
		{
			Inventory->SetCredits(SaveObject->PlayerCredits);
			Inventory->SetCargo(SaveObject->PlayerCargo);
		}
		if (UMissionComponent* Missions = Owner->FindComponentByClass<UMissionComponent>())
		{
			Missions->ActiveMissions = SaveObject->ActiveMissions;
			Missions->AvailableMissions = SaveObject->AvailableMissions;
			Missions->CompletedMissions = SaveObject->CompletedMissions;
			Missions->FailedMissions = SaveObject->FailedMissions;
		}
		if (UFactionComponent* Factions = Owner->FindComponentByClass<UFactionComponent>())
		{
			Factions->FactionStandings = SaveObject->FactionStandings;
			Factions->FactionRelationships = SaveObject->FactionRelationships;
		}
		if (UShieldComponent* Shield = Owner->FindComponentByClass<UShieldComponent>())
		{
			Shield->SetCurrentShield(SaveObject->CurrentShield);
		}
		if (UDamageComponent* Damage = Owner->FindComponentByClass<UDamageComponent>())
		{
			Damage->CurrentHullHealth = SaveObject->CurrentHullHealth;
		}
		Owner->SetActorLocationAndRotation(SaveObject->PlayerLocation, SaveObject->PlayerRotation);
	}

	UE_LOG(LogTemp, Log, TEXT("LoadGame '%s': restored (saved %s)"), *SlotName.ToString(), *SaveObject->SaveTimestamp.ToString());
	return true;
}

void USaveGameComponent::AutoSave()
{
	// Called on: dock, undock, mission complete, quantum travel arrive, pirate defeated
	SaveGame(TEXT("AutoSave"));
}
